let stage=2,closed=false,timer;
const $=id=>document.getElementById(id),escape=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
SCENARIOS.forEach((s,i)=>$('scenario').add(new Option(`${i+1}. ${s.name}`,i)));
function toast(message){$('toast').textContent=message;$('toast').style.display='block';clearTimeout(timer);timer=setTimeout(()=>$('toast').style.display='none',3500)}
function openState(){ $('state-frame').hidden=false;$('editor').hidden=true;$('state-tab').classList.add('active');$('file-tab').classList.remove('active');$('breadcrumbs').textContent='.uspec › changes › refund-window › state'; }
function showEditor(name,text,edit=false){$('state-frame').hidden=true;$('editor').hidden=false;$('file-tab').textContent='Ⓜ '+name.split('/').pop()+'　×';$('file-tab').classList.add('active');$('state-tab').classList.remove('active');$('breadcrumbs').textContent=name.replaceAll('/',' › ');$('editor-text').textContent=text;$('editor-text').contentEditable=edit?'true':'false';$('editor-actions').innerHTML=edit?'<button id="save-draft">Save sample draft</button>':'';if(edit)$('save-draft').onclick=()=>{sessionStorage.setItem('uspec-draft',$('editor-text').textContent);toast('Sample draft saved in this browser.');};}
function modal(title,html){$('dialog-title').textContent=title;$('dialog-body').innerHTML=html;$('dialog').showModal()}
function doc(key){const text=key.includes('rules.md')?SAMPLE_DOC:key.includes('api.md')?'# Payments API\n\n## Refunds\n\nPOST /payments/{id}/refund\n\nA refund can be requested within 30 days after delivery.\nThe refund is paid to the original payment method.':`# ${key.split('/').pop().replace('.md','')}\n\nSample document for the current UI preview.\n\nThis document belongs to ${key.split('/').slice(0,-1).join('/')}.`;showEditor('docs/'+key,text);$('node-section').open=true;}
const changeText='# Extend the refund window\n\n## Why\n\nCustomers miss the current 14-day refund window.\n\n## What changes\n\nExtend the refund window from 14 days to 30 days after delivery.\nKeep the existing payout method and refund approval process.\n\n## Worked example\n\nAn order delivered on 1 March can be refunded until 31 March.\n\n## Out of scope\n\nChanges to payment methods or refund approval roles.';
function action(a,key){if(a==='runAgents'){if(stage===1||stage===3||stage===2){toast('This stage is waiting for your approval. Review and approve to continue.');openState();}else if(stage===0)setStage(1);else if(stage===4)setStage(5);else toast('The change is ready to close.');}else if(a==='approve'){setStage(Math.min(5,stage+1));toast('Approved in the preview. Showing the next stage.');}else if(a==='reject'){setStage(Math.max(0,stage-1));toast('Rejected in the preview. Returned to the previous stage.');}else if(a==='showDiff'){modal('api.md · before writer ↔ now','<p>Sample writer update</p><pre>## Refund eligibility\n<span class="diff-minus">− Refunds are allowed within 14 days after delivery.</span>\n<span class="diff-plus">+ Refunds are allowed within 30 days after delivery.</span>\n\nPayout: original payment method.</pre><button id="diff-approve">Approve</button>');$('diff-approve').onclick=()=>{$('dialog').close();action('approve');};}else if(a==='showLog'){showEditor('writer.log',`# ${SCENARIOS[stage].name}\nproject: example_product · change: refund-window\n\n--- input\nRead change.md and the current spec context.\n\n→ Read docs/product/support/refunds/rules.md\n→ Read docs/system/services/payments/api.md\n\n--- result\n${stage===4?'Implementing payments plan.':'Waiting for user review.'}\n\n[Simulated log for this UI preview]`);}else if(a==='openDoc')doc(key||'product/support/refunds/rules.md');else if(a==='openChangeMd')showEditor('.uspec/changes/refund-window/change.md',sessionStorage.getItem('uspec-draft')||changeText,true);else if(a==='openPlan')showEditor(`.uspec/changes/refund-window/plans/${key||'payments'}.md`,`---\nnodes:\n  - ${key==='refunds'?'experience/ops-console/refunds':'system/services/payments'}\nafter: ${key==='refunds'?'[payments]':'[]'}\n---\n# ${key==='refunds'?'Update the refund screen':'Extend refund eligibility'}\n\n1. Update the eligibility check from 14 to 30 days.\n2. Update boundary tests for day 30 and day 31.\n3. Run the relevant tests and verify the spec.`);else if(a==='close'){closed=true;showEditor('refund-window · state','refund-window is closed.');$('change-tree').innerHTML='<p>No open changes.</p>';$('change-title').textContent='No open changes';toast('Sample change closed. Use Reset to start again.');}else if(a==='stop'){toast('Sample agents stopped. Use Run agents to continue.');$('output').textContent='refund-window: agents stopped by user';}else if(a==='continue')modal('Continue in Claude Code','<p>In the extension, this opens a Claude Code terminal session with the change context.</p><p>This browser preview does not launch agents. You can edit the sample <code>change.md</code> instead.</p><button id="edit-change">Open change.md</button>'),$('edit-change').onclick=()=>{$('dialog').close();action('openChangeMd');};else if(a==='context')showEditor('Context','product/support/refunds\n\n# Files\nancestors: docs/product/overview.md\nupstream: docs/product/glossary/overview.md\ndocuments: docs/product/support/refunds/rules.md\nchange: .uspec/changes/refund-window/change.md');}
function setStage(n){closed=false;stage=Number(n);$('scenario').value=stage;$('state-frame').src=`state-${stage}.html`;$('change-title').innerHTML='⌄ refund-window <small>active</small>';openState();const s=SCENARIOS[stage];let h='';if(s.runs.length)h+='<details open><summary>Agents</summary>'+s.runs.map(r=>`<button data-action="showLog">${r.state==='running'?'◌':'?'} ${escape(r.title)} <small>${escape(r.state)}</small></button>`).join('')+'</details>';h+='<details open><summary>Next</summary><button data-state>'+escape(s.name)+'</button></details>';if(s.docs.length)h+='<details open><summary>Documents</summary>'+['affected','pending','updated','no-change'].map(state=>{const ds=s.docs.filter(d=>d.state===state);return ds.length?`<details ${state==='updated'?'':'open'}><summary>${escape(state)} <small>${ds.length}</small></summary>${ds.map(d=>`<button title="${escape(d.document)}" data-file="${escape(d.document)}">Ⓜ ${escape(d.document.split('/').slice(-2).join('/'))}</button>`).join('')}</details>`:'';}).join('')+'</details>';if(s.plans.length)h+='<details open><summary>Plans</summary>'+s.plans.map(p=>`<button data-plan="${p.plan}">▤ ${p.plan} <small>${p.state}</small></button>`).join('')+'</details><details><summary>Implementation</summary><button data-plan="payments">system/services/payments</button><button data-plan="refunds">experience/ops-console/refunds</button></details>';h+='<button data-action="openChangeMd">Ⓜ change.md</button><button data-status>⚙ status.yaml</button>';$('change-tree').innerHTML=h;$('status-text').textContent='uspec: refund-window · '+s.summary;$('output').textContent='uspec · sample project loaded\nrefund-window: '+s.name.toLowerCase()+(s.runs.some(r=>r.state==='needs-approval')?' — waiting for approval':'');}
$('scenario').onchange=e=>setStage(e.target.value);$('reset').onclick=()=>setStage(0);$('refresh').onclick=()=>{setStage(stage);toast('Preview refreshed.');};$('sidebar-run').onclick=()=>action('runAgents');$('state-tab').onclick=$('change-title').onclick=$('show-state').onclick=openState;$('file-tab').onclick=()=>action('openChangeMd');$('dismiss').onclick=()=>$('dialog').close();$('dialog').onclick=e=>{if(e.target===$('dialog'))$('dialog').close();};$('info').onclick=()=>modal('About this preview','<p>The main change-state panel is generated from the current extension renderer. The surrounding VS Code shell and sidebar are recreated for browser use.</p><p>Use <strong>Preview stage</strong> to inspect every step. Buttons simulate transitions; they do not execute agents or modify the project.</p>');$('search').onclick=()=>{ $('spec-section').open=true;toast('Open a document in the Spec Tree.');};$('new').onclick=()=>{setStage(0);action('openChangeMd');};
document.addEventListener('click',e=>{const el=e.target.closest('[data-file],[data-plan],[data-action],[data-state],[data-status],[data-nav],[data-panel],[data-type]');if(!el)return;if(el.dataset.file)doc(el.dataset.file);else if(el.dataset.plan)action('openPlan',el.dataset.plan);else if(el.dataset.action)action(el.dataset.action);else if(el.hasAttribute('data-state'))openState();else if(el.hasAttribute('data-status'))showEditor('.uspec/changes/refund-window/status.yaml',`baseline: a82c4d7913f\ndocuments:\n${SCENARIOS[stage].docs.map(d=>`  ${d.document}: {state: ${d.state}}`).join('\n')}`);else if(el.dataset.nav)$(el.dataset.nav==='spec'?'spec-section':'changes-section').open=true;else if(el.dataset.panel){document.querySelectorAll('[data-panel]').forEach(b=>b.classList.toggle('active',b===el));$('output').textContent=el.dataset.panel==='problems'?'No problems detected.':el.dataset.panel==='terminal'?'example_product % uspec change next refund-window\n'+SCENARIOS[stage].name:'uspec · '+SCENARIOS[stage].summary;}else if(el.dataset.type)showEditor('node-type.yaml',`name: ${el.dataset.type}\ndocuments: [overview, rules]\n\n# Representative type details for the preview.`);});
window.addEventListener('message',e=>{if(e.origin!==location.origin||e.source!==$('state-frame').contentWindow||!e.data?.uspecPreview)return;action(e.data.action,e.data.key||e.data.plan);});setStage(2);
